<section class="archive-head"><span>Search</span><h1>Search the site</h1><form class="big-search" action="/search"><input name="q" value="<?= e($q) ?>" placeholder="What are you looking for?"><button>Search</button></form></section><section class="posts archive"><?php foreach($results as $item):?><article class="post-card"><div class="post-inner"><div class="date"><?= e($item['type']) ?></div><h2><a href="<?= $item['type']==='post'?'/blog/':'/' ?><?= e($item['slug']) ?>"><?= e($item['title']) ?></a></h2><p><?= e($item['excerpt']?:'Open to read more.') ?></p></div></article><?php endforeach;?><?php if($q!==''&&!$results):?><div class="empty">No results for “<?= e($q) ?>”.</div><?php endif;?></section>